sys_ui_action.script:
if (typeof window == 'undefined') {
    // -------- Server-side Code --------
    (function serverSideFunction() {

        var rating = current.u_rating;
        var comments = current.u_comments;

        if (!rating || !comments) {
            gs.addErrorMessage('Please provide Rating and Comments before submitting feedback.');
            return;
        }

        var feedbackGR = new GlideRecord('x_1790227_event_ma_feedback');
        feedbackGR.initialize();
        feedbackGR.u_event = current.u_event_id;  // Reference to Event Record
        feedbackGR.u_rating = rating;
        feedbackGR.u_comments = comments;

        var insertedSysId = feedbackGR.insert();
        if (insertedSysId) {
            gs.addInfoMessage('Thank you for your feedback!');
			action.setRedirectURL();
        } else {
            gs.addErrorMessage('Failed to submit feedback.');
        }

    })();

} else {
    // -------- Client-side Code --------
    function clientSideFunction() {
        var rating = g_form.getValue('u_rating');
        var comments = g_form.getValue('u_comments');

        if (!rating || !comments) {
            alert('Please fill in Rating and Comments before submitting feedback.');
            return false; // Prevent form submission
        }

        g_form.submit();  // Submits form & triggers server-side function
    }
    clientSideFunction();
}
